const request = $input.first().json;
const envelope = request.body && typeof request.body === 'object' ? request.body : request;
const acceptedSchemas = new Set(['dominium.toa.technician-locations.v1', 'dominium.toa.technician-location-batch.v2']);
if (!acceptedSchemas.has(envelope.schema)) throw new Error('Schema GPS inválido');
if (!Array.isArray(envelope.resources)) throw new Error('Lote sem resources');
const safeKey = (value) => String(value || 'sem-id').replace(/[.#$\[\]\/]/g, '_').slice(0, 180);
const hash = (value) => { const text = JSON.stringify(value); let result = 2166136261; for (let index = 0; index < text.length; index += 1) { result ^= text.charCodeAt(index); result = Math.imul(result, 16777619); } return (result >>> 0).toString(16); };
const updates = {};
let accepted = 0; let planned = 0; let stops = 0; let snapshots = 0; let ignored = 0;
for (const resource of envelope.resources) {
  const technician = resource.technician && typeof resource.technician === 'object' ? resource.technician : {};
  const technicianKey = safeKey(technician.login || technician.id);
  if (technicianKey === 'sem-id') { ignored += 1; continue; }
  const gpsReal = Array.isArray(resource.gps_real) ? resource.gps_real : (resource.points || []);
  const serviceStops = Array.isArray(resource.service_stops) ? resource.service_stops : (resource.visits || []);
  const plannedRoute = Array.isArray(resource.planned_route) ? resource.planned_route : [];
  const metadata = (base) => { updates[`${base}/technician_id`] = String(technician.id || ''); updates[`${base}/technician_login`] = String(technician.login || ''); updates[`${base}/technician_name`] = String(technician.name || technician.login || technician.id || ''); updates[`${base}/bucket`] = String(resource.bucket || ''); updates[`${base}/profile`] = String(resource.profile || ''); updates[`${base}/updated_at`] = envelope.publishedAt || envelope.captured_at || new Date().toISOString(); };
  const snapshotDate = String(resource.visit_snapshot_date || '').slice(0, 10);
  const validSnapshot = /^\d{4}-\d{2}-\d{2}$/.test(snapshotDate);
  const replacePlanned = Boolean(resource.replace_planned_route || resource.replace_visits) && validSnapshot;
  const replaceStops = Boolean(resource.replace_service_stops || resource.replace_visits) && validSnapshot;
  const snapshotPlanned = {}; const snapshotStops = {};
  for (const point of gpsReal) {
    const observedAt = String(point.observed_at || ''); const day = observedAt.slice(0, 10); const latitude = Number(point.latitude); const longitude = Number(point.longitude);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day) || !Number.isFinite(latitude) || !Number.isFinite(longitude)) { ignored += 1; continue; }
    const base = `dominium/toa/history/technicianLocations/${day}/technicians/${technicianKey}`; metadata(base); updates[`${base}/last_at`] = observedAt;
    const pointKey = safeKey(`${observedAt}_${hash([latitude, longitude])}`);
    updates[`${base}/gpsReal/${pointKey}`] = { observed_at: observedAt, latitude, longitude, accuracy_m: Number.isFinite(Number(point.accuracy_m)) ? Number(point.accuracy_m) : null, speed_kmh: Number.isFinite(Number(point.speed_kmh)) ? Number(point.speed_kmh) : null, heading: Number.isFinite(Number(point.heading)) ? Number(point.heading) : null, altitude_m: Number.isFinite(Number(point.altitude_m)) ? Number(point.altitude_m) : null, activity_id: String(point.activity_id || '') }; accepted += 1;
  }
  for (const routePoint of plannedRoute) {
    const latitude = Number(routePoint.latitude); const longitude = Number(routePoint.longitude); const day = String(routePoint.date || routePoint.scheduled_at || snapshotDate).slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day) || !Number.isFinite(latitude) || !Number.isFinite(longitude)) { ignored += 1; continue; }
    const base = `dominium/toa/history/technicianLocations/${day}/technicians/${technicianKey}`; metadata(base);
    const routeKey = safeKey(`${routePoint.activity_id || routePoint.marker_label || 'rota'}_${latitude.toFixed(6)}_${longitude.toFixed(6)}`);
    const value = { scheduled_at: String(routePoint.scheduled_at || ''), latitude, longitude, marker_label: String(routePoint.marker_label || ''), activity_id: String(routePoint.activity_id || '') };
    if (replacePlanned && day === snapshotDate) snapshotPlanned[routeKey] = value; else updates[`${base}/plannedRoute/${routeKey}`] = value; planned += 1;
  }
  for (const stop of serviceStops) {
    const latitude = Number(stop.latitude); const longitude = Number(stop.longitude); const day = String(stop.date || stop.scheduled_at || snapshotDate).slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day) || !Number.isFinite(latitude) || !Number.isFinite(longitude)) { ignored += 1; continue; }
    const base = `dominium/toa/history/technicianLocations/${day}/technicians/${technicianKey}`; metadata(base);
    const stopKey = safeKey(`${stop.activity_id || 'atividade'}_${latitude.toFixed(6)}_${longitude.toFixed(6)}`);
    const value = { date: day, scheduled_at: String(stop.scheduled_at || ''), latitude, longitude, marker_label: String(stop.marker_label || ''), activity_id: String(stop.activity_id || ''), os_number: String(stop.os_number || ''), contract: String(stop.contract || ''), service: String(stop.service || ''), status: String(stop.status || ''), service_window: String(stop.service_window || '') };
    if (replaceStops && day === snapshotDate) snapshotStops[stopKey] = value; else updates[`${base}/serviceStops/${stopKey}`] = value; stops += 1;
  }
  if (replacePlanned) { const base = `dominium/toa/history/technicianLocations/${snapshotDate}/technicians/${technicianKey}`; metadata(base); updates[`${base}/plannedRoute`] = Object.keys(snapshotPlanned).length ? snapshotPlanned : null; snapshots += 1; }
  if (replaceStops) { const base = `dominium/toa/history/technicianLocations/${snapshotDate}/technicians/${technicianKey}`; metadata(base); updates[`${base}/serviceStops`] = Object.keys(snapshotStops).length ? snapshotStops : null; snapshots += 1; }
}
if (!accepted && !planned && !stops && !snapshots) throw new Error('Nenhum dado técnico válido no lote');
return [{ json: { updates, summary: { accepted, planned, stops, snapshots, ignored, paths: Object.keys(updates).length } } }];
